-- Tabel untuk material_access
DROP TABLE IF EXISTS "material_access";
CREATE TABLE IF NOT EXISTS "material_access" (
  "id" TEXT,
  "updated_at" TEXT,
  "created_at" TEXT,
  "material_id" TEXT,
  "view_count" TEXT,
  "user_id" TEXT,
  "source" TEXT,
  "first_accessed_at" TEXT,
  "last_accessed_at" TEXT
);

